 raw=(stage/name).read_bytes()
 blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\x00'+raw).hexdigest()
 if blob!=sha:raise RuntimeError('integrity check failed '+name)
 if name.endswith('.php'):
  exe=shutil.which('php') or '/usr/local/bin/php'
  p=subprocess.run([exe,'-l',str(stage/name)],capture_output=True,text=True,timeout=10)
